while true; do echo "$(date +%T) max=$(adb shell 'cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_max_freq /sys/devices/system/cpu/cpu2/cpufreq/scaling_max_freq /sys/devices/system/cpu/cpu7/cpufreq/scaling_max_freq' | tr '\r\n' '  ') gpu=$(adb shell 'cat /sys/class/kgsl/kgsl-3d0/max_gpuclk /sys/class/kgsl/kgsl-3d0/gpuclk 2>/dev/null' | tr '\r\n' '  ') $(adb shell "dumpsys thermalservice | sed -n '/Current temperatures from HAL/,/Current cooling/p' | grep -E 'mName=(skin|battery)' | head -2 | grep -o 'mValue=[0-9.]*'" | tr '\r\n' '  ')"; sleep 30; done
